#include <iostream>
#include <string>
#include <utility>

struct Book {
    std::string title;
    int pages{};
    bool operator==(const Book&) const = default;
};

int main()
{
    const Book original{"Atlas", 120};
    Book copy = original;
    copy.title = "Revised";
    Book assigned{"Draft", 1};
    assigned = original;
    Book moved = std::move(copy);
    std::cout << original.title << ' ' << moved.title << '\n';
    std::cout << std::boolalpha << (assigned == original) << '\n';
}
